package dev.jarofcucumbers.prscraft;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.network.PacketDistributor;
import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** All virtual changes are validated and committed on the actual simulator owner block. */
public final class SimulatorNetwork{
    public record Request(BlockPos pos,int node,String action,CompoundTag data) implements CustomPacketPayload{
        public static final Type<Request> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(PRSCraft.ID,"simulator"));public static final StreamCodec<RegistryFriendlyByteBuf,Request> CODEC=new StreamCodec<>(){public Request decode(RegistryFriendlyByteBuf b){return new Request(b.readBlockPos(),b.readInt(),b.readUtf(32),b.readNbt());}public void encode(RegistryFriendlyByteBuf b,Request p){b.writeBlockPos(p.pos);b.writeInt(p.node);b.writeUtf(p.action,32);b.writeNbt(p.data);}};public Type<? extends CustomPacketPayload> type(){return TYPE;}
    }
    public static SimulatorBlockEntity available(ServerPlayer p,BlockPos pos){if(p.distanceToSqr(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5)>64||!p.serverLevel().hasChunkAt(pos)||!p.mayBuild()||!p.serverLevel().mayInteract(p,pos)||!(p.level().getBlockEntity(pos) instanceof SimulatorBlockEntity sim))return null;return sim;}
    public static void register(RegisterPayloadHandlersEvent e){e.registrar("1").playToServer(Request.TYPE,Request.CODEC,(request,context)->context.enqueueWork(()->{if(!(context.player() instanceof ServerPlayer player))return;var sim=available(player,request.pos);if(sim==null||request.data==null)return;long tick=player.level().getGameTime();var budget=player.getPersistentData();String key="prscraft_sim_"+(request.action.equals("device")?"device":"edit");if(!request.action.equals("board")){if(budget.contains(key)&&tick-budget.getLong(key)<(request.action.equals("device")&&!request.data.getBoolean("save")&&request.data.getCompound("request").getString("action").isEmpty()?10:2))return;budget.putLong(key,tick);}String error="";try{var doc=new SimulatorDocument(sim.document().save());var d=request.data;boolean graph=true;
        switch(request.action){
            case "refresh" -> {}
            case "add" -> doc.add(d.getString("kind"),d.getDouble("x"),d.getDouble("y"));
            case "move" -> doc.move(request.node,d.getDouble("x"),d.getDouble("y"));
            case "remove" -> doc.remove(request.node);
            case "rotate" -> {var n=doc.node(request.node);var dir=Direction.byName(n.getString("facing"));n.putString("facing",dir.getClockWise().getName());}
            case "wire" -> {var check=doc.world(player.level().registryAccess(),tick);var from=check.getBlockEntity(SimulatorDocument.position(d.getInt("from")));var to=check.getBlockEntity(SimulatorDocument.position(request.node));if(!(from instanceof RadioBlockEntity a)||!(to instanceof RadioBlockEntity b)||a.isSource()&&!a.settings().transmit()||b.isSource()&&b.settings().transmit()||d.getString("input").equals("B")&&!java.util.Set.of("adder","correlator","orthogonality_meter").contains(b.kind()))throw new IllegalArgumentException("sim_wire");doc.wire(d.getInt("from"),request.node,d.getString("input"),SignalBudget.Medium.valueOf(d.getString("medium")),new CableSettings(d.getDouble("metres"),d.getDouble("damage"),d.getDouble("dispersion"),d.getBoolean("environment")));}
            case "unwire" -> doc.wires().removeIf(t->((CompoundTag)t).getInt("to")==request.node&&((CompoundTag)t).getString("input").equals(d.getString("input")));
            case "weather" -> doc.weather(d.getString("weather"));
            case "open","device","media","codebook","codebook_edit","record","save_template","apply_template","clear_card","board" -> {
                var world=doc.world(player.level().registryAccess(),tick);var entity=world.getBlockEntity(SimulatorDocument.position(request.node));graph=false;
                if(entity instanceof DrawingBoardEntity board){if(request.action.equals("board")){int[] pixels=java.util.BitSet.valueOf(d.getByteArray("mask")).stream().toArray();int color=d.getInt("color");var drawBudget=player.getPersistentData();if(drawBudget.getLong("prscraft_sim_draw_tick")!=tick){drawBudget.putLong("prscraft_sim_draw_tick",tick);drawBudget.putInt("prscraft_sim_draw_cost",0);}int spent=drawBudget.getInt("prscraft_sim_draw_cost");if(spent+pixels.length>16384)throw new IllegalArgumentException("sim_limit");drawBudget.putInt("prscraft_sim_draw_cost",spent+pixels.length);if(color<0||color>16||pixels.length>16384)throw new IllegalArgumentException("sim_node");board.paint(BoardPixels.checked(pixels),color);}world.persist();sim.commit(doc);sendBoard(player,request.pos,request.node,board,request.action.equals("open"));return;}
                if(!(entity instanceof RadioBlockEntity radio))throw new IllegalArgumentException("sim_node");
                if(request.action.equals("device")){if(d.getBoolean("save"))DeviceConfiguration.apply(radio,d.getCompound("request"));else if(d.getCompound("request").getString("action").equals("view")){var v=d.getCompound("request");if(v.contains("plot"))radio.configurePlot(PlotSettings.read(v.getCompound("plot")));if(v.contains("graphLayers"))radio.graph(v.getInt("graphLayers"),v.getInt("graphTerms"));if(v.contains("correlationView"))radio.correlationView(v.getBoolean("correlationView"));}else if(d.getCompound("request").getString("action").equals("media")){world.persist();sim.commit(doc);sendMedia(player,request.pos,request.node,radio);return;}}
                if(request.action.equals("codebook_edit")){String mapping=d.getString("mapping");SymbolCodebook.parse(mapping);var card=new net.minecraft.world.item.ItemStack(PRSCraft.CODEBOOK_CARD.get());var t=new CompoundTag();t.putString("codebook",mapping);card.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(t));radio.media.setStackInSlot(2,card);}
                if(request.action.equals("clear_card"))radio.media.setStackInSlot(2,net.minecraft.world.item.ItemStack.EMPTY);
                if(request.action.equals("save_template")){var item=new net.minecraft.world.item.ItemStack(PRSCraft.TEMPLATE.get());item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(DeviceConfiguration.template(radio)));radio.media.setStackInSlot(0,item);}
                if(request.action.equals("apply_template"))radio.applyTemplate();
                if(request.action.equals("record")){var capture=CircuitCapture.capture(world,radio.getBlockPos());var item=new net.minecraft.world.item.ItemStack(PRSCraft.DATA_CARD.get());item.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(capture));radio.media.setStackInSlot(1,item);}
                world.persist();sim.commit(doc);
                if(java.util.Set.of("media","record","save_template","apply_template","clear_card").contains(request.action)){sendMedia(player,request.pos,request.node,radio);return;}
                if(request.action.equals("codebook")||request.action.equals("codebook_edit")){var data=new CompoundTag();data.putString("kind","codebook_editor");data.putString("mapping",radio.media.getStackInSlot(2).isEmpty()?SymbolCodebook.DEFAULT:CodebookCardItem.mapping(radio.media.getStackInSlot(2)));data.putBoolean("inDevice",true);data.putString("error","");snapshot(player,request.pos,request.node,data,request.action.equals("codebook"));return;}
                var capture=CircuitCapture.capture(world,radio.getBlockPos());snapshot(player,request.pos,request.node,capture,request.action.equals("open")||d.getCompound("request").getString("action").equals("reopen"));return;
            }
            default -> throw new IllegalArgumentException("sim_action");
        }sim.commit(doc);if(graph)send(player,request.pos,false,"");
    }catch(IllegalArgumentException ex){error=ex.getMessage();if(request.action.equals("device")){try{var world=sim.document().world(player.level().registryAccess(),tick);var capture=CircuitCapture.capture(world,SimulatorDocument.position(request.node));capture.putString("error",error);snapshot(player,request.pos,request.node,capture,false);}catch(IllegalArgumentException ignored){send(player,request.pos,false,error);}}else send(player,request.pos,false,error);}}));}
    public static void send(ServerPlayer player,BlockPos pos,boolean open,String error){var sim=available(player,pos);if(sim==null)return;var data=sim.document().save();data.putString("kind","simulator");data.putString("error",error);PacketDistributor.sendToPlayer(player,new RadioNetwork.Snapshot(pos,open,data));}
    private static void snapshot(ServerPlayer p,BlockPos root,int node,CompoundTag data,boolean open){if(data.getBoolean("connected")&&data.getIntArray("received").length==512)Milestones.award(p,"simulator_lab");data.putLong("simulatorRoot",root.asLong());data.putBoolean("simulated",true);data.putInt("simulatorNode",node);PacketDistributor.sendToPlayer(p,new RadioNetwork.Snapshot(SimulatorDocument.position(node),open,data));}
    private static void sendMedia(ServerPlayer p,BlockPos root,int node,RadioBlockEntity radio){var data=new CompoundTag();data.putString("kind","sim_media");data.putBoolean("templatePresent",!radio.media.getStackInSlot(0).isEmpty());var card=radio.media.getStackInSlot(1);if(card.has(net.minecraft.core.component.DataComponents.CUSTOM_DATA))data.put("recording",card.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag());snapshot(p,root,node,data,true);}
    private static void sendBoard(ServerPlayer p,BlockPos root,int node,DrawingBoardEntity board,boolean open){var data=new CompoundTag();data.putString("kind","sim_board");data.putByteArray("pixels",board.pixels());snapshot(p,root,node,data,open);}
}
